#include <stdio.h>
#include <stdlib.h>

#define GRID_SIZE 6

int grid[GRID_SIZE][GRID_SIZE];
int visited[GRID_SIZE][GRID_SIZE];
int dist[GRID_SIZE][GRID_SIZE];
int q_row[GRID_SIZE * GRID_SIZE];
int q_col[GRID_SIZE * GRID_SIZE];

int main(int argc, char **argv) {
    // Initialize grid and visited arrays
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = 0;
            visited[i][j] = 0;
            dist[i][j] = 0;
        }
    }

    // Read input from command line arguments
    for (int i = 1; i < argc; i++) {
        int row = strtol(argv[i], NULL, 10);
        int col = strtol(argv[i + 1], NULL, 10);
        grid[row][col] = 1;
        i++;
    }

    // Perform BFS
    int q_size = 0;
    q_row[0] = 0;
    q_col[0] = 0;
    visited[0][0] = 1;
    dist[0][0] = 0;
    while (q_size < GRID_SIZE * GRID_SIZE) {
        int row = q_row[q_size];
        int col = q_col[q_size];
        q_size++;
        for (int i = 0; i < 4; i++) {
            int new_row = row + (i % 2 == 0 ? -1 : 1);
            int new_col = col + (i % 2 == 1 ? -1 : 1);
            if (new_row >= 0 && new_row < GRID_SIZE && new_col >= 0 && new_col < GRID_SIZE && !visited[new_row][new_col] && grid[new_row][new_col] == 1) {
                visited[new_row][new_col] = 1;
                dist[new_row][new_col] = dist[row][col] + 1;
                q_row[q_size] = new_row;
                q_col[q_size] = new_col;
                q_size++;
            }
        }
    }

    // Print result
    printf("dist=%d\n", dist[GRID_SIZE - 1][GRID_SIZE - 1]);

    return 0;
}
